  @MainActor func testHTTPDepthProfileAndInterpolationShareNativeCollectionTransaction()async throws{let h=AutomationTests();try await h.withService(pressedMouseButtons:{0}){service,doc in let s=doc.store;for depth in PixelDepth.allCases{for group in [false,true]{var source=try self.fixture(depth,group:group);source.workingICC=try ColorManagement.importedProfile(XCTUnwrap(CGColorSpace(name:CGColorSpace.displayP3)?.copyICCData() as Data?),depth:depth);let ids=group ? [try XCTUnwrap(source.activeLayerID)]:source.layers.map(\.id);for method in Resampling.allCases{s.session=EditorSession(document:source);s.selectedLayerIDs=Set(ids);try service.share(doc);let matrix=Transform2D(a:1,b:0.1,c:0.2,d:1,tx:3,ty:2),code=try await h.edit(service,doc,"layers.transform",["layerIDs":ids.map(\.uuidString),"matrix":[matrix.a,matrix.c,matrix.tx,matrix.b,matrix.d,matrix.ty,0,0,1],"interpolation":method.rawValue]);XCTAssertEqual(code,200);var expected=source;try Command.transformLayers(.init(layerIDs:ids,matrix:matrix,interpolation:method)).apply(to:&expected);XCTAssertEqual(s.document,expected);XCTAssertEqual(try NativeArchive.encodeChunked(s.document),try NativeArchive.encodeChunked(expected));XCTAssertEqual(s.groupSelectionIDs,Set(ids));_=await s.requestHistory(redo:false).value;XCTAssertEqual(s.document,source)}}}}}
  @MainActor func testInvalidBusyStaleRevokedCancelledAndChangedSelectionsAreAtomic()async throws{let h=AutomationTests();try await h.withService(pressedMouseButtons:{0}){service,doc in let source=try self.fixture(),s=doc.store;s.session=EditorSession(document:source);self.select(s);try service.share(doc);let ids=source.layers.map(\.id),params:[String:Any]=["layerIDs":ids.map(\.uuidString),"matrix":[1,0,3,0,1,2,0,0,1]];for extra:[String:Any] in [["layerIDs":[]],["layerIDs":["bad"]],["layerIDs":[ids[0].uuidString,ids[0].uuidString]],["matrix":[0,0,0,0,0,0,0,0,0]],["interpolation":"bad"],["unknown":1]]{let code=try await h.edit(service,doc,"layers.transform",params.merging(extra){_,b in b});XCTAssertEqual(code,400);XCTAssertEqual(s.document,source)};let projective=try await h.edit(service,doc,"layers.transform",params.merging(["matrix":[1,0,0,0,1,0,-0.1,0,1]]){_,b in b});XCTAssertEqual(projective,422);let stale=try await h.edit(service,doc,"layers.transform",params,revision:"old");XCTAssertEqual(stale,409);s.beginTransform();let busy=try await h.edit(service,doc,"layers.transform",params);XCTAssertEqual(busy,409);s.cancelTransform();let gate=CollectionTransformGate();defer{gate.release()};s.layerCollectionTransformPreparation={_,request in gate.wait();try Task.checkCancellation();return .transformLayers(request)};let task=Task{try await h.edit(service,doc,"layers.transform",params)};let until=Date().addingTimeInterval(10);while !s.geometryBusy && Date()<until{await Task.yield()};service.revoke(try XCTUnwrap(service.shares.first?.id));gate.release();let code=try await task.value;XCTAssertEqual(code,409);XCTAssertEqual(s.document,source);let native=CollectionTransformGate();defer{native.release()};s.layerCollectionTransformPreparation={_,request in native.wait();try Task.checkCancellation();return .transformLayers(request)};s.beginTransform();let session=try XCTUnwrap(s.selectionTransform);s.commitTransform();s.cancelTransform();native.release();await session.commitTask