  func testAnalyticalLayerCollectionOutputsCapturedForIndependentReader()throws{
    var rows:[[String:Any]]=[];for matrix in [Transform2D.translation(5,3),.translation(15,0) * .scale(-1,1),.translation(0,12) * .scale(1,-1),.translation(-5,-3)]{var d=try CraftDocument(width:20,height:16),a=Layer(name:"A",content:.raster(try Surface(width:3,height:2,fill:Pixel(1,0,0)))),b=Layer(name:"B",content:.raster(try Surface(width:4,height:3,fill:Pixel(0,0,1))));a.x=2;a.y=3;b.x=9;b.y=6;d.layers=[a,b];d.activeLayerID=b.id;try Command.transformLayers(.init(layerIDs:d.layers.map(\.id),matrix:matrix,interpolation:.nearest)).apply(to:&d);let out=try Renderer.render(d).surface;var rgba:[Int]=[];for y in 0..<16{for x in 0..<20{let p=out.pixel(x:x,y:y);rgba += [p.r,p.g,p.b,p.a].map{Int((unit($0)*255).rounded())}}};rows.append(["matrix":[matrix.a,matrix.b,matrix.c,matrix.d,matrix.tx,matrix.ty],"rgba":rgba])}
    if let path=ProcessInfo.processInfo.environment["PHOTATO_TEST_CAPTURE_DIR"]{let dir=URL(fileURLWithPath:path);try FileManager.default.createDirectory(at:dir,withIntermediateDirectories:true);try JSONSerialization.data(withJSONObject:["width":20,"height":16,"rows":rows],options:.sortedKeys).write(to:dir.appendingPathComponent("layer-collection-transform-analytical.json"))}
